package edu.bis701.exp04;
import org.apache.hadoop.conf.Configuration;import org.apache.hadoop.fs.Path;import org.apache.hadoop.io.*;import org.apache.hadoop.mapreduce.Job;import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;
public class MovieLensAnalysis{public static void main(String[]a)throws Exception{if(a.length!=2)throw new IllegalArgumentException("MovieLensAnalysis <input> <output>");Job j=Job.getInstance(new Configuration(),"MovieLens Ratings Analysis");j.setJarByClass(MovieLensAnalysis.class);j.setMapperClass(MovieMapper.class);j.setReducerClass(MovieReducer.class);j.setMapOutputKeyClass(Text.class);j.setMapOutputValueClass(Text.class);j.setOutputKeyClass(Text.class);j.setOutputValueClass(Text.class);FileInputFormat.addInputPath(j,new Path(a[0]));FileOutputFormat.setOutputPath(j,new Path(a[1]));System.exit(j.waitForCompletion(true)?0:1);}}
